+
+function numericValue(value: DatabaseRow[string]): number | undefined {
+  if (typeof value === "number") return value;
+  if (typeof value !== "string") return undefined;
+
+  const parsedValue = Number.parseFloat(value);
+  return Number.isNaN(parsedValue) ? undefined : parsedValue;
+}
+
+/**
+ * Recombines group averages using their row counts. If the query does not
+ * include a count metric, callers retain the previous unweighted fallback.
+ */
+function calculateAverage(
+  data: DatabaseRow[],
+  metric: string,
+  countMetric: string | undefined,
+  values: number[],
+): number {
+  if (!countMetric) return applyAggregation(values, "avg");
+
+  const weightedRows = data
+    .map((row) => ({
+      value: numericValue(row[metric]),
+      count: numericValue(row[countMetric]),
+    }))
+    .filter(
+      (row): row is { value: number; count: number } =>
+        row.value !== undefined && row.count !== undefined,
+    );
+  const totalCount = weightedRows.reduce((sum, row) => sum + row.count, 0);
+
+  return totalCount === 0
+    ? 0
+    : weightedRows.reduce((sum, row) => sum + row.value * row.count, 0) /
+        totalCount;
+}
